eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   PRISM_CATEGORIES: () => (/* binding */ PRISM_CATEGORIES),\n/* harmony export */   PRISM_SYSTEM_PROMPT: () => (/* binding */ PRISM_SYSTEM_PROMPT)\n/* harmony export */ });\nconst PRISM_CATEGORIES = {\n    attribution: {\n        key: \"attribution\",\n        name: \"Attribution & Sourcing\",\n        shortDesc: \"Anonymous sourcing, passive voice, or unattributed claims\",\n        description: 'Examines who is credited for facts and claims. Highlights anonymous sources, passive voice distancing (\"it was decided\"), and unverified claims presented as established facts without primary documentation.',\n        color: \"#8C531B\",\n        bgWash: \"#FDF6EC\",\n        borderColor: \"#E8D4BE\",\n        badgeBg: \"#FDF6EC\",\n        badgeText: \"#8C531B\",\n        example: '\"Officials familiar with the discussions confirmed...\", \"It has been widely reported that...\"',\n        whyItMatters: \"Vague attribution shifts authority onto unnamed actors, shielding claims from independent scrutiny and obscuring institutional accountability.\"\n    },\n    evaluative: {\n        key: \"evaluative\",\n        name: \"Evaluative & Loaded Language\",\n        shortDesc: \"Value-laden adjectives, adverbs, and emotional framing\",\n        description: 'Detects subjective adjectives, adverbs, and metaphors that steer reader sentiment (e.g., \"reckless\", \"historic triumph\", \"desperate gamble\", \"unprecedented crisis\") instead of using neutral descriptive prose.',\n        color: \"#9E4A28\",\n        bgWash: \"#F9EFEA\",\n        borderColor: \"#E8B6A2\",\n        badgeBg: \"#F9EFEA\",\n        badgeText: \"#9E4A28\",\n        example: '\"The administration finally buckled...\", \"in a stunning display of incompetence...\"',\n        whyItMatters: \"Loaded vocabulary primes the reader with an emotional verdict before they can evaluate the underlying factual evidence.\"\n    },\n    certainty: {\n        key: \"certainty\",\n        name: \"Certainty & Speculation\",\n        shortDesc: \"Hedging, speculative forecasts, or false absolute certainty\",\n        description: 'Analyzes modal framing—contrasting unearned high-certainty assertions (\"will inevitably collapse\") with speculative hedging (\"could potentially signal\") to shape anticipation and perceived inevitability.',\n        color: \"#A66B24\",\n        bgWash: \"#FAF3EA\",\n        borderColor: \"#E8D4BE\",\n        badgeBg: \"#FAF3EA\",\n        badgeText: \"#A66B24\",\n        example: '\"This decision will undoubtedly trigger...\", \"Analysts suspect this may indicate...\"',\n        whyItMatters: \"Over-certainty manufactures urgency, while excessive hedging can subtly plant unverified doubts or speculative narratives.\"\n    },\n    claims: {\n        key: \"claims\",\n        name: \"Claims vs. Evidence\",\n        shortDesc: \"Asserted conclusions lacking cited data or corroborating evidence\",\n        description: \"Identifies factual assertions, economic projections, or causal claims made without supporting citations, empirical metrics, or linkable primary research.\",\n        color: \"#434D80\",\n        bgWash: \"#EEF0F8\",\n        borderColor: \"#BCC2E2\",\n        badgeBg: \"#EEF0F8\",\n        badgeText: \"#434D80\",\n        example: '\"Studies prove the economy has suffered immense damage...\", \"Experts unanimously agree...\"',\n        whyItMatters: \"Treating contested hypotheses as self-evident truths bypasses empirical validation and creates an illusion of consensus.\"\n    },\n    primacy: {\n        key: \"primacy\",\n        name: \"Emphasis & Structural Primacy\",\n        shortDesc: \"Information placement, top-billing versus buried nuance\",\n        description: \"Analyzes where specific elements appear in the narrative hierarchy—what is headlined and lead-paragraphed versus what is relegated to the final paragraph or buried as an afterthought.\",\n        color: \"#3B6B56\",\n        bgWash: \"#EBF1EE\",\n        borderColor: \"#B9D5C8\",\n        badgeBg: \"#EBF1EE\",\n        badgeText: \"#3B6B56\",\n        example: \"Leading with political controversy while placing positive technical metrics in paragraph 14.\",\n        whyItMatters: \"Most readers only scan the first two paragraphs; structural ordering dictates what sticks in public memory.\"\n    },\n    omission: {\n        key: \"omission\",\n        name: \"Omissions & Blind Spots\",\n        shortDesc: \"Vital context present in competing coverage but ignored here\",\n        description: \"Pinpoints systemic omissions—crucial counter-arguments, relevant historical precedent, stakeholder reactions, or trade-offs that competing outlets highlight but the target text omits.\",\n        color: \"#3C567A\",\n        bgWash: \"#ECF1F6\",\n        borderColor: \"#B6CBDE\",\n        badgeBg: \"#ECF1F6\",\n        badgeText: \"#3C567A\",\n        example: \"Covering a new subsidy without noting its tax-funded cost or impacted small businesses.\",\n        whyItMatters: \"What an article leaves out often shapes perception more powerfully than what it includes.\"\n    },\n    emotional: {\n        key: \"emotional\",\n        name: \"Emotional Framing\",\n        shortDesc: \"Rhetoric engineered to evoke fear, anger, moral outrage, or euphoria\",\n        description: \"Identifies sensationalist framing devices, fear appeals, moral outrage cues, or patriotic triumphalism designed to provoke visceral reactions rather than calm deliberation.\",\n        color: \"#7D374B\",\n        bgWash: \"#F6ECF0\",\n        borderColor: \"#DFBAC5\",\n        badgeBg: \"#F6ECF0\",\n        badgeText: \"#7D374B\",\n        example: '\"Citizens are left in sheer panic as chaos looms...\", \"A monumental triumph for the nation...\"',\n        whyItMatters: \"Affective framing hijacks critical appraisal by stimulating fight-or-flight or tribal solidarity instincts.\"\n    }\n};\nconst PRISM_SYSTEM_PROMPT = `You are PERSPECTA's PRISM Framing Analysis Engine.\nPERSPECTA is an analytical media literacy tool.\nCore Philosophy: \"Don't tell people what to think. Show them how the story is being told.\"\n\nSTRICT GUARDRAILS:\n1. You are NOT a political bias scorer (NEVER output \"70% Left/Right\").\n2. You are NOT a truth oracle or fake-news detector.\n3. Every detected signal MUST be an EXACT VERBATIM substring copied directly from the article text.\n   - If the quote does not appear verbatim in the source text, it will be automatically rejected.\n4. For each signal:\n   - \"quoted_text\": Exact verbatim excerpt (2 to 12 words).\n   - \"category\": One of [\"attribution\", \"evaluative\", \"certainty\", \"claims\", \"primacy\", \"omission\", \"emotional\"].\n   - \"explanation\": Neutral, matter-of-fact breakdown explaining how this specific phrase or framing structure influences reader perception. DO NOT express moral judgments.\n   - \"confidence\": Float between 0.65 and 0.98.\n   - \"alternative_phrasing\": A neutral, strictly descriptive rewrite of the quote.\n   - \"framing_effect\": Brief phrase on the perceptual impact (e.g., \"Amplifies urgency\", \"Distances responsibility\", \"Primes negative sentiment\").\n\nFor cross-article comparative findings:\n- Identify how the outlets framed the same central event with contrasting emphasis, tone, chosen actors, and omitted context.\n`;\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./lib/prism-rubric.ts\n");

